use std::collections::HashMap;

pub struct Cache {
    capacity: usize,
    ttl: i64,
    store: HashMap<String, i32>,
}

impl Cache {
    pub fn new(capacity: usize, ttl: i64) -> Self {
        Cache { capacity, ttl, store: HashMap::new() }
    }

    pub fn put(&mut self, key: &str, value: i32, now: i64) {
        self.store.insert(key.to_string(), value);
    }

    pub fn get(&mut self, key: &str, now: i64) -> Option<i32> {
        self.store.get(key).copied()
    }
}

