use lru_cache::Cache;

#[test]
fn capacity_evicts_least_recently_used() {
    let mut c = Cache::new(2, 1000);
    c.put("a", 1, 0);
    c.put("b", 2, 1);
    c.get("a", 2);
    c.put("c", 3, 3);
    assert_eq!(c.get("a", 4), Some(1));
    assert_eq!(c.get("b", 4), None);
    assert_eq!(c.get("c", 4), Some(3));
}

#[test]
fn get_refreshes_recency() {
    let mut c = Cache::new(2, 1000);
    c.put("a", 1, 0);
    c.put("b", 2, 1);
    c.get("a", 2);
    c.get("b", 3);
    c.put("c", 3, 4);
    assert_eq!(c.get("a", 5), None);
    assert_eq!(c.get("b", 5), Some(2));
}

#[test]
fn ttl_expiry_independent_of_capacity() {
    let mut c = Cache::new(5, 10);
    c.put("a", 1, 0);
    assert_eq!(c.get("a", 9), Some(1));
    assert_eq!(c.get("a", 10), None);
}

