use std::collections::HashMap;

struct Entry {
    value: i32,
    stored_at: i64,
}

pub struct Cache {
    capacity: usize,
    ttl: i64,
    store: HashMap<String, Entry>,
    order: Vec<String>, // front = most recently used
}

impl Cache {
    pub fn new(capacity: usize, ttl: i64) -> Self {
        Cache { capacity, ttl, store: HashMap::new(), order: Vec::new() }
    }

    fn touch(&mut self, key: &str) {
        self.order.retain(|k| k != key);
        self.order.insert(0, key.to_string());
    }

    pub fn put(&mut self, key: &str, value: i32, now: i64) {
        if !self.store.contains_key(key) && self.store.len() >= self.capacity {
            if let Some(oldest) = self.order.pop() {
                self.store.remove(&oldest);
            }
        }
        self.store.insert(key.to_string(), Entry { value, stored_at: now });
        self.touch(key);
    }

    pub fn get(&mut self, key: &str, now: i64) -> Option<i32> {
        let expired = match self.store.get(key) {
            Some(e) => now - e.stored_at >= self.ttl,
            None => return None,
        };
        if expired {
            self.store.remove(key);
            self.order.retain(|k| k != key);
            return None;
        }
        self.touch(key);
        self.store.get(key).map(|e| e.value)
    }
}

